[728] = { en = "To the Undercity for Yagyin's Digest", tier = 3,
  t = "Naar de Undercity voor Yagyin's Digest",
  d = "De tablet vertelt veel. Maar niet genoeg! Lang niet genoeg!$B$BEr is een boek, een samenvatting die Yagyin lang geleden heeft geschreven. De... mensen voor wie ik ben gevlucht... zij bewaren dit boek op veel plaatsen. En de meest geleerden onder hen bestuderen het. Er staat enorm veel kennis in. Kennis om ons te beschermen!$B$BGa naar Keeper Bel'dugur in de Undercity van Lordaeron. Laat hem dit zegel zien, dan denkt hij dat je een van hen bent. Vraag hem om Yagyin's Digest... en breng het naar mij!",
  o = "Breng de Sigil of the Hammer naar Keeper Bel'dugur in de Undercity.",
  p = "Ah, ik zie een enthousiaste $C. Ben je hier om iets te leren van mijn verzameling? Goed!$B$BMaar let op: kennis geeft de sterken macht... maar de zwakken maakt ze gek.",
  c = "Wees discreet met je tekens, $C. Er zijn mensen die niet geloven dat onze belofte rechtvaardig is.$B$BEn er zijn mensen die ons zouden willen zien falen, als ze van ons wisten.$B$BWe moeten altijd voorzichtig zijn. En waakzaam. En geduldig.",
  g = { {"samenvatting", "digest, summary"}, {"gevlucht", "fled (vluchten)"}, {"bewaren", "to keep, to store"}, {"geleerden", "learned ones, scholars"}, {"bestuderen", "to study"}, {"kennis", "knowledge"}, {"zegel", "seal, sigil"}, {"enthousiaste", "eager (enthousiast)"}, {"verzameling", "collection"}, {"discreet", "discreet"}, {"rechtvaardig", "righteous, just"}, {"belofte", "pledge, promise"}, {"falen", "to fail"}, {"waakzaam", "watchful"}, {"geduldig", "patient"} },
},

[1419] = { en = "Coyote Thieves", tier = 3,
  t = "Coyotedieven",
  d = "Heb je al veel dagen in de Badlands doorgebracht, $c? Heb je de hitte gevoeld? Heb je gevochten tegen de beesten die over de stoffige vlaktes zwerven? Het wordt tijd dat je dat doet.$B$BCrag coyotes zijn een taai ras. Taai, en brutaal genoeg om Kargath binnen te sluipen en van onze voedselvoorraad te stelen. Help de buitenpost van deze dieven af!$B$BJaag op crag coyotes, $N. Jaag op ze en breng me hun kaakbeenderen. Breng me er genoeg, en misschien geloof ik je dan als je zegt dat je de Badlands kent.",
  o = "Breng 30 Coyote Jawbones naar Neeka Bloodscar in Kargath.",
  p = "Heb je de kaakbeenderen?",
  c = "Dat is een mooie verzameling kaakbeenderen, $N. Nu scheuren die coyotes niet meer door onze voorraden op zoek naar restjes.$B$BGoed gedaan. De coyotes van de Badlands zijn geen makkelijke prooi. Wat je hebt gedaan, laat me zien dat je het hier misschien wel overleeft.",
  g = { {"doorgebracht", "spent (doorbrengen)"}, {"stoffige", "dusty (stoffig)"}, {"vlaktes", "plains (vlakte)"}, {"zwerven", "to roam, to wander"}, {"taai", "tough"}, {"ras", "breed"}, {"brutaal", "bold, cheeky"}, {"sluipen", "to creep, to sneak"}, {"voedselvoorraad", "food supply"}, {"buitenpost", "outpost"}, {"kaakbeenderen", "jawbones (kaakbeen)"}, {"restjes", "scraps (restje)"}, {"prooi", "prey"}, {"overleeft", "survive (overleven)"} },
},

[1420] = { en = "Report to Helgrum", tier = 3,
  t = "Meld je bij Helgrum",
  d = "Ik heb een nieuw verslag geschreven voor Helgrum in Stonard. Breng het naar hem.$B$BEn als je jezelf een koerier noemt, raak dan niet de weg kwijt. En laat je niet verslaan door een vijand.",
  o = "Breng Neeka's Report naar Helgrum the Swift in Stonard.",
  p = "Je bent terug. Heb je een verslag?",
  c = "Dank je, $N. In Neeka's verslag zie ik dat de Alliance ook zijn eigen problemen heeft. En misschien ontdekken we dat we sommige vijanden met elkaar delen.",
  g = { {"meld je", "report (zich melden)"}, {"verslag", "report"}, {"koerier", "courier, runner"}, {"de weg kwijt", "lose your way (de weg kwijtraken)"}, {"verslaan", "to defeat"}, {"ontdekken", "to discover"}, {"delen", "to share"} },
},

[1372] = { en = "Nothing But The Truth", tier = 3,
  t = "Niets dan de waarheid",
  d = "Onze expeditie werd op bevel van Varimathras gestuurd om het lagere Azeroth te verkennen.$b$bToen ik op verkenning was, zag ik een menselijke Infiltrator die Beggar's Haunt bespioneerde. Voordat ik hem kon arresteren, hebben een paar van onze orkse... broeders... hem gevangengenomen. Ze hebben hem meegenomen naar Stonard, hun vesting in de Swamp of Sorrows.$b$bIk wil onze orkse bondgenoten... helpen. Ze hebben ons kamp hier niet gezien, maar toch wil ik ze een handje helpen.$b$bWerk samen met Faustin hier om een... waarheidsserum te maken voor onze vriend in Stonard.",
  o = "Spreek met Apothecary Faustin in Beggar's Haunt.",
  c = "Zraedus vertelde me net over die nieuwsgierige kleine Infiltrator, voordat je kwam.$b$bDat is inderdaad een flink probleem. Het laatste wat we nodig hebben, is een bemoeial die rondsnuffelt bij Beggar's Haunt.$b$bIk weet zeker dat de orks van Stonard staan te popelen om te horen wat onze vriend te zeggen heeft. Omdat ze onze bondgenoten zijn, ahum, moeten we ze helpen om alle informatie uit de mens te krijgen die ze kunnen.$b$bWerk met me samen, $n, dan brengen we een waarheidsserum naar Stonard.$b$bVoor de Horde!$b$b...zei ik dat goed?",
  g = { {"op bevel van", "at the behest of"}, {"verkennen", "to survey, to scout"}, {"bespioneerde", "was spying on (bespioneren)"}, {"arresteren", "to apprehend, to arrest"}, {"orkse", "orcish (orks)"}, {"broeders", "brethren (broeder)"}, {"gevangengenomen", "captured (gevangennemen)"}, {"vesting", "stronghold"}, {"een handje helpen", "to lend a hand"}, {"waarheidsserum", "truth serum"}, {"nieuwsgierige", "nosey (nieuwsgierig)"}, {"bemoeial", "busybody"}, {"rondsnuffelt", "sniffs around (rondsnuffelen)"}, {"staan te popelen", "are anxious, can't wait (popelen)"} },
},

[1383] = { en = "Nothing But The Truth", tier = 3,
  t = "Niets dan de waarheid",
  d = "Ik heb precies het juiste serum in gedachten. Het gaat met de waarheid om op precies de manier waarop je met de waarheid hoort om te gaan.$B$BVoor dit brouwsel heb ik een paar Shadow Panther-harten uit het moeras nodig. Ik heb ook de betoverde schimmel nodig van de Mire Lord die daar woont. Ik weet zeker dat iemand die zo bekwaam is als jij, $N, hem kan overtuigen om er wat van af te staan.$B$BHet moeilijke deel wordt het vinden van een Deepstrider-tumor uit het verre Desolace. Heel zelden worden de reuzen daar ziek, en dan groeit er een tumor.$B$BEn nu: op pad!",
  o = "Apothecary Faustin in Beggar's Haunt heeft 5 Shadow Panther Hearts, Mire Lord Fungus en een Deep Strider Tumor nodig.",
  p = "Die Infiltrator in Stonard gaat vast.... open... als hij mijn speciale serum drinkt. Haha!$b$bDe ingrediënten zijn helemaal niet makkelijk te krijgen. Er zijn genoeg Shadow Panthers in het moeras, maar genoeg harten verzamelen voor ons doel kan zwaar zijn. En de Mire Lord kan echt een lastig beest zijn.$b$bEn de Deepstrider-tumoren zijn vreselijk moeilijk te vinden. Maar de chemische reactie die ik eruit kan halen, is ongeëvenaard.",
  c = "Prachtig, $n! En precies op tijd. Zraedus zegt dat de Infiltrator hersteld is van zijn wonden en klaar is om door de orks ondervraagd te worden.$b$bGeef me even een moment om het gif-- ik bedoel, om het waarheidsserum klaar te maken.",
  g = { {"in gedachten", "in mind"}, {"hoort", "should, ought to (horen)"}, {"betoverde", "enchanted (betoveren)"}, {"schimmel", "fungus"}, {"bekwaam", "able, capable"}, {"overtuigen", "to persuade"}, {"af te staan", "to part with (afstaan)"}, {"reuzen", "giants (reus)"}, {"op pad", "off you go"}, {"ingrediënten", "ingredients (ingrediënt)"}, {"doel", "purpose"}, {"lastig", "fussy, difficult"}, {"ongeëvenaard", "second to none, unequalled"}, {"hersteld", "recovered (herstellen)"}, {"ondervraagd", "questioned (ondervragen)"}, {"gif", "poison"} },
},

[1388] = { en = "Nothing But The Truth", tier = 3,
  t = "Niets dan de waarheid",
  d = "Alles gaat volgens plan, $n. Geef dit waarheidsserum aan Deathstalker Zraedus. Hij laat je zien hoe je het... op de juiste manier toedient.$b$bHaha!",
  o = "Geef Faustin's Truth Serum aan Deathstalker Zraedus in Beggar's Haunt.",
