[1391] = { en = "Nothing But The Truth", tier = 3,
  t = "Niets dan de waarheid",
  d = "We moeten met een zekere voorzichtigheid te werk gaan. Je gaat daar natuurlijk niet zomaar naar binnen wandelen om die dwaas over te halen om Faustin's brouwsel te drinken, toch?$b$bMaar als er één ding is waar die mensen geen nee tegen kunnen zeggen, dan is het drank. Ik neem Faustin's serum en meng het door dit bier. Ik garandeer je dat die arme sukkel geen moment zal aarzelen als het gaat om een biertje achterover te slaan.$b$bHaast je naar Stonard in de Swamp of Sorrows, $n. En hou onze kleine missie mooi stil...",
  o = "Breng Zraedus's Brew naar Infiltrator Marksen in Stonard.",
  p = "Heb alsjeblieft medelijden met me! Ik heb informatie die verder gaat dan de grenzen van bondgenootschappen. Ik ben geen aanhanger van de Horde, maar er is politiek verraad aan de gang dat onthuld moet worden!",
  c = "Een drankje voor mij? Wat aardig. Ze hebben me al dagen niets laten drinken. Laat me dit even opdrinken, en dan vertel ik je wat ik te weten ben gekomen....",
  g = { {"voorzichtigheid", "discretion, caution"}, {"te werk gaan", "to operate, to proceed"}, {"dwaas", "fool"}, {"over te halen", "to convince (overhalen)"}, {"drank", "booze, drink"}, {"garandeer", "guarantee (garanderen)"}, {"sukkel", "sap, dope"}, {"aarzelen", "to hesitate"}, {"achterover te slaan", "to chug, to knock back (achteroverslaan)"}, {"haast je", "make haste (zich haasten)"}, {"medelijden", "mercy, pity"}, {"aanhanger", "sympathizer, supporter"}, {"verraad", "treachery"}, {"onthuld", "revealed (onthullen)"}, {"te weten ben gekomen", "have learned (te weten komen)"} },
},

[2862] = { en = "War on the Woodpaw", tier = 3,
  t = "Oorlog tegen de Woodpaw",
  d = "De gnolls... ze zijn meer dan alleen lastig. Ze zijn een voortdurende bedreiging voor het bestaan van dit kamp! Het maakt niet uit of ze oorspronkelijk uit Feralas komen of niet. Als we niet vastberadener tegen ze optreden, worden we uit de hele streek verdreven.$B$BDe aanvallen van de gnolls op het kamp zijn de laatste tijd heftiger geworden. We hebben je hulp nodig om hun aantal te verkleinen. Breng me tien van hun manen, dan beloon ik je royaal voor je moeite.$B$BGa!",
  o = "Breng 10 Woodpaw Gnoll Manes naar Hadoken Swiftstrider in Camp Mojache.",
  p = "We drijven ze terug, en toch blijven ze aanvallen! Iemand of iets moet ze tot razernij drijven... o, je bent terug, hè $n? Heb je de manen die ik nodig heb voor de beloning?",
  c = "Dit bewijst dat je goed begonnen bent, $n. Je vaardigheden als soldaat verdienen lof.$B$BJe bent niet de enige die ik deze taak geef. Velen voor jou hebben tegen ze gevochten, en vroeger hielden we ze met onze inspanningen op afstand. Maar de laatste tijd proberen ze veel vaker naar het noorden door te dringen, ons gebied in. Hun aanvallen zijn ook wreder geworden... bijna alsof ze wanhopig zijn.$B$BMaar ik heb een plan, $n, waarmee we misschien voorgoed met ze kunnen afrekenen...",
  g = { {"voortdurende", "constant (voortdurend)"}, {"bedreiging", "threat"}, {"bestaan", "existence"}, {"oorspronkelijk", "originally, indigenous"}, {"vastberadener", "more resolutely (vastberaden)"}, {"optreden", "to take action"}, {"verdreven", "driven out (verdrijven)"}, {"heftiger", "more fevered, fiercer (heftig)"}, {"manen", "manes"}, {"royaal", "handsomely, generously"}, {"razernij", "frenzy"}, {"lof", "praise"}, {"inspanningen", "efforts (inspanning)"}, {"wreder", "more savage (wreed)"}, {"wanhopig", "desperate"} },
},

[782] = { en = "Broken Alliances", tier = 3,
  t = "Gebroken bondgenootschappen",
  d = "Tijdens de Second War was de Horde bondgenoot van de draak Deathwing. Daardoor weten we dat twee van zijn luitenanten, Blacklash en Hematus, opgesloten zijn in Lethlor Ravine, ver in het oosten. We moeten onze verdorven bondgenoten van vroeger het zwijgen opleggen, zodat de Horde haar eer terugkrijgt!$B$BWe hebben Tho'grun en zijn groep ogre-huurlingen ingehuurd om ons te helpen het Sign of the Earth te krijgen. Dat is een sleutel die je nodig hebt om de gevangenis van de draken te openen. Maar Tho'grun heeft ons verraden. Hij heeft ons overmeesterd en het voor zichzelf genomen. Ga naar Camp Boff en neem het terug!",
  o = "Dood Boss Tho'grun en breng het Sign of the Earth naar Gorn in Kargath.",
  p = "Het verraad van Tho'grun... is het een wonder dat de ogres geen deel meer uitmaken van de Horde? Ik zal blij zijn als hij dood is en het Sign of the Earth terug is.$B$BAls je hem nog niet hebt gedood, verspil dan geen tijd en ga naar Camp Boff. Het ligt ten zuidoosten van Kargath.",
  c = "Nu Tho'grun dood is en zijn lijk wordt kaalgepikt door de woestijnwind en de aasgieren, raken de ogres in verwarring. Het is maar een kleine overwinning, maar ze zal leiden tot een veel grotere.$B$BHet Sign of the Earth is nu in ons bezit, en we kunnen de gevangenis van de zwarte draken in Lethlor openen. We zullen ze bevrijden uit hun eindeloze gevangenschap, al is het alleen om ze naar hun ondergang te sturen!",
  g = { {"bondgenootschappen", "alliances (bondgenootschap)"}, {"bondgenoot", "ally"}, {"luitenanten", "lieutenants (luitenant)"}, {"opgesloten", "imprisoned (opsluiten)"}, {"verdorven", "depraved"}, {"het zwijgen opleggen", "to silence"}, {"eer", "honour"}, {"huurlingen", "mercenaries (huurling)"}, {"verraden", "betrayed (verraden)"}, {"overmeesterd", "overwhelmed (overmeesteren)"}, {"verraad", "betrayal"}, {"kaalgepikt", "picked clean (kaalpikken)"}, {"aasgieren", "scavenging buzzards, vultures (aasgier)"}, {"bezit", "possession"}, {"gevangenschap", "imprisonment"}, {"ondergang", "doom, downfall"} },
},

[2863] = { en = "Alpha Strike", tier = 3,
  t = "Alfa-aanval",
  d = "Het plan is om verschillende leiders van de gnolls - Alphas, zoals ze zichzelf noemen - snel na elkaar uit te schakelen. Als we ze zo snel en precies kunnen verwoesten, ontstaat er chaos in hun gelederen. Misschien dringt het dan ook tot hun dikke, door vlooien gebeten koppen door dat we ze kunnen en zullen vernietigen!$B$BIk wil dat jij de boodschapper van mijn wil bent. Schakel binnen een uur vijf van hun Alphas uit om dit te laten werken, $N, anders blijven we in deze patstelling zitten!",
  o = "Dood 5 Woodpaw Alphas en keer binnen een uur terug naar Hadoken Swiftstrider.",
  p = "De tijd raakt op, $n! Als je hier niet bent om te melden dat je de Alphas hebt uitgeschakeld, dan verspil je tijd!",
  c = "Je hebt gedaan wat ik vroeg, en daarvoor groet ik je. Neem deze kleine beloning aan als vergoeding voor je moeite, $n.$B$BNu hun aantal kleiner is en hun leiders gedood zijn, zullen de gnolls wel twee keer nadenken voordat ze het kamp bestormen. Maar daarmee is het probleem nog niet opgelost...$B$BEr moet een reden zijn waarom de gnolls zo razend zijn geworden. Voordat ze de kans krijgen om zich te hergroeperen, wil ik weten wat de oorzaak is.",
  g = { {"uit te schakelen", "to take down (uitschakelen)"}, {"verwoesten", "to devastate"}, {"gelederen", "ranks (gelid)"}, {"dringt tot ... door", "sinks in (doordringen)"}, {"vlooien", "fleas (vlo)"}, {"boodschapper", "messenger"}, {"patstelling", "impasse, stalemate"}, {"raakt op", "is running out (opraken)"}, {"vergoeding", "compensation"}, {"bestormen", "to storm"}, {"opgelost", "solved (oplossen)"}, {"razend", "frenzied, furious"}, {"hergroeperen", "to regroup"}, {"oorzaak", "cause"} },
},

[2902] = { en = "Woodpaw Investigation", tier = 3,
  t = "Onderzoek bij de Woodpaw",
  d = "Gnolls zijn niet het scherpste mes in de la, maar ze hebben vast wel een soort opgeschreven strategie over wat ze de laatste tijd doen. Als we die plannen vinden, dan weten we beter waarom ze zo opgefokt zijn.$B$BIk wil dat je teruggaat naar de Woodpaw en alles zoekt wat op hun gevechtsplannen lijkt. Ze moeten iets hebben; hun aanvallen waren te goed gecoördineerd om zonder plannen te zijn uitgevoerd. Vind ze, en kom bij me terug als je ze hebt.",
  o = "Vind de gevechtsplannen van de gnolls ergens in de gnollkampen ten zuiden van Camp Mojache.",
  c = "Als je de kaart bekijkt, zie je dat het de gevechtsplannen zijn die Hadoken Swiftstrider wil hebben. Er staan veel pijlen op de kaart, die misschien troepenbewegingen voorstellen. Maar de meeste lijken naar het zuiden te gaan, en niet naar het noorden, waar Camp Mojache ligt.$B$BOp een ander deel van de kaart staat een tekening van wat volgens jou een groot soort insect is, met allerlei streepjes eronder. Als je naar de gnolls kijkt, stelt het misschien hun verliezen tegen de onbekende beestjes voor...",
  g = { {"onderzoek", "investigation"}, {"niet het scherpste mes in de la", "not the sharpest tool in the shed"}, {"opgeschreven", "documented, written down (opschrijven)"}, {"opgefokt", "worked up"}, {"gevechtsplannen", "battle plans (gevechtsplan)"}, {"gecoördineerd", "coordinated (coördineren)"}, {"uitgevoerd", "carried out (uitvoeren)"}, {"pijlen", "arrows (pijl)"}, {"troepenbewegingen", "troop movements"}, {"voorstellen", "to represent"}, {"streepjes", "tick marks (streepje)"}, {"verliezen", "losses (verlies)"}, {"beestjes", "bugs (beestje)"} },
},

[2903] = { en = "The Battle Plans", tier = 3,
  t = "De gevechtsplannen",
  d = "Je hebt de gevechtsplannen van de gnolls gevonden. Nu hoef je de plannen alleen nog terug te brengen naar Hadoken Swiftstrider in Camp Mojache. Misschien kan hij of iemand anders daar beter begrijpen wat de gnolls van plan zijn.",
  o = "Breng de Woodpaw Battle Plans naar Hadoken Swiftstrider in Camp Mojache.",
  p = "Welkom terug, $n. Heb je echt bewijs gevonden van de plannen van de gnolls?",
  c = "Ah, dit is precies wat we nodig hadden. Ik ben niet zo goed in het ontcijferen van de meeste krabbels op deze kaart, maar ik heb in mijn tijd genoeg gevechtsplannen gezien om te begrijpen wat er met de gnolls aan de hand is. Het lijkt erop dat ze nu op twee fronten oorlog voeren. Eén front is tegen ons... maar het grootste deel van hun kracht lijkt naar een vijand in het zuiden te gaan.$B$BEr is hier meer aan de hand dan je op het eerste gezicht zou denken. Misschien wordt het tijd om uit te zoeken wie die andere vijand echt is.",
  g = { {"gevechtsplannen", "battle plans (gevechtsplan)"}, {"van plan", "up to, planning"}, {"bewijs", "evidence, proof"}, {"ontcijferen", "to decipher"}, {"krabbels", "scrawlings (krabbel)"}, {"aan de hand", "going on"}, {"fronten", "fronts (front)"}, {"kracht", "energy, strength"}, {"op het eerste gezicht", "at first sight"}, {"uit te zoeken", "to figure out (uitzoeken)"} },
},

[2975] = { en = "The Ogres of Feralas", tier = 3,
  t = "De ogres van Feralas",
  d = "Je kunt de gevolgen van de Gordunni-ogrestam in deze streek moeilijk over het hoofd zien. Kijk om je heen, $N; alleen al hun aanwezigheid laat littekens na op dit land. We moeten ze terugdringen voordat ze zich nog verder in Feralas uitbreiden.$B$BVolg de rivier naar het noorden, dan vind je hun buitenpost. Verklein hun aantal, $N. We moeten ze laten zien dat hun soort hier niet welkom is.",
  o = "Rok Orhan in Camp Mojache wil dat je 10 Gordunni Ogres, 10 Gordunni Ogre-Magi en 5 Gordunni Brutes doodt.",
  p = "Wees snel, $N. Of is de taak die ik je gaf te moeilijk?",
  c = "Uitstekend, $N. Na verloop van tijd zal het land genezen. We mogen niet opgeven.",
  g = { {"gevolgen", "effects (gevolg)"}, {"ogrestam", "ogre tribe"}, {"over het hoofd zien", "to overlook"}, {"aanwezigheid", "presence"}, {"littekens", "scars (litteken)"}, {"terugdringen", "to push back"}, {"uitbreiden", "to expand"}, {"buitenpost", "outpost"}, {"verklein", "decrease (verkleinen)"}, {"na verloop van tijd", "in time"}, {"genezen", "to heal"}, {"opgeven", "to give up"} },
},

