[2987] = { en = "Gordunni Cobalt", tier = 3,
  t = "Gordunni-kobalt",
  d = "Ik ben net in Feralas aangekomen, en ik heb gehoord dat de Gordunni-ogres die hier in de wildernis wonen interessante mineralen hebben. Wie weet wat ze ermee doen, maar ze beschermen dat spul wel heel goed! Ze laten het niet zomaar rondslingeren; nee, ze begraven het, zodat mensen zoals ik er niet aan kunnen komen.$B$BAls je wilt, geef ik je mijn schep. Ga naar de Gordunni Outpost ten noorden van hier en graaf wat Gordunni-kobalt voor me op. Zoek naar de blauwe gloed, en begin dan te graven!",
  o = "Orwin Gizzmick in Camp Mojache wil 12 monsters van Gordunni Cobalt.",
  p = "Ga daarheen en begin te graven!$B$BIk moet nog overal heen en veel mensen zien -- tijd is geld!",
  c = "Perfect! Ik neem deze mee op mijn verdere reis, $N. Ik weet zeker dat ik iemand vind die een flinke prijs voor dit kobalt wil betalen.$B$BHier, neem dit voor je moeite.",
  g = { {"kobalt", "cobalt"}, {"wildernis", "wilds, wilderness"}, {"mineralen", "minerals (mineraal)"}, {"spul", "stuff"}, {"rondslingeren", "to lie around"}, {"begraven", "to bury"}, {"schep", "shovel"}, {"graaf op", "dig up (opgraven)"}, {"gloed", "glow"}, {"monsters", "samples (monster)"}, {"flinke", "pretty, hefty (flink)"} },
},

[2203] = { en = "Badlands Reagent Run II", tier = 3,
  t = "Ingrediënten uit de Badlands II",
  d = "Je hebt me erg goed geholpen, $c. Ik zou je graag belonen met het recept voor het brouwsel dat ik je eerder gaf... maar ik wil je eerst een taak geven die vrij gevaarlijk is. Luister naar mijn verzoek.$B$BIn dit kistje zitten drie lege thaumaturgievaten. Er zit een afstemmingsaura in die het bloed van een scorched guardian dragon opzuigt. Als je er één op het beest gebruikt, wordt het erg kwaad, dus wees gewaarschuwd. Breng ze naar mij als ze alle drie gevuld zijn.$B$BDoe dit, en het recept is van jou.",
  o = "Gebruik de empty thaumaturgy vessels op scorched guardian dragons in de Badlands. Breng ze naar Jarkal Mossmeld in Kargath als ze gevuld zijn.",
  p = "Heb je de vaten gebruikt om het bloed van de scorched guardian dragon te halen dat ik nodig heb? Ja, ik weet dat het een gevaarlijke taak is... maar het recept voor mijn herstellende brouwsel wacht op je succes. Risico en beloning, vriend... risico en beloning...",
  c = "Van de ene alchemist aan de andere: ik groet je. Hier, neem dit recept en prent het goed in je geheugen. Moge het je hetzelfde succes en dezelfde beloningen brengen als het mij door de jaren heen heeft gebracht.",
  g = { {"belonen", "to reward"}, {"recept", "recipe"}, {"brouwsel", "brew"}, {"verzoek", "request"}, {"kistje", "lockbox, small chest (kist)"}, {"thaumaturgievaten", "thaumaturgy vessels (thaumaturgievat)"}, {"afstemmingsaura", "attunement aura"}, {"opzuigt", "drains, sucks up (opzuigen)"}, {"gewaarschuwd", "warned (waarschuwen)"}, {"gevuld", "filled (vullen)"}, {"herstellende", "restorative (herstellend)"}, {"beloning", "reward"}, {"prent het in je geheugen", "commit it to memory (inprenten)"}, {"Moge", "may (mogen)"} },
},

[2980] = { en = "The Ogres of Feralas", tier = 3,
  t = "De ogres van Feralas",
  d = "Nu je hebt bewezen dat je een echte vechter bent, vertrouw ik erop dat je de moed hebt om verder te gaan met deze taak.$B$BReis naar de High Wilderness, ten zuidwesten van hier. Daar staan verlaten en verwoeste gebouwen, op land dat ooit van de nachtelfen was. Zoek deze ruïnes. Als je de verdorde bomen en het ontheiligde land ziet, vind je de Gordunni. Drijf ze terug.$B$BDeze ogres zijn veel sterker dan degene die je eerder hebt bevochten, $N. Wees op je hoede.",
  o = "Rok Orhan in Camp Mojache wil dat je 10 Gordunni Shaman, 10 Gordunni Warlocks en 5 Gordunni Maulers doodt.",
  p = "Heb je de ruïnes gevonden, $N?",
  c = "Je hebt bewezen dat je een betrouwbare bondgenoot bent op wie ik kan rekenen, $N.",
  g = { {"bewezen", "proven (bewijzen)"}, {"moed", "courage"}, {"verlaten", "abandoned"}, {"verwoeste", "destroyed (verwoest)"}, {"nachtelfen", "night elves (nachtelf)"}, {"ruïnes", "ruins (ruïne)"}, {"verdorde", "withered (verdord)"}, {"ontheiligde", "desecrated (ontheiligen)"}, {"bevochten", "fought (bevechten)"}, {"wees op je hoede", "be aware, be careful"}, {"betrouwbare", "trustworthy (betrouwbaar)"}, {"rekenen op", "to depend on"} },
},

[2973] = { en = "A New Cloak's Sheen", tier = 3,
  t = "De glans van een nieuwe mantel",
  d = "Gegroet, $c. Ik ben met mijn metgezellen naar Feralas gereisd voor een opdracht van onze meesters in Orgrimmar.$B$BMijn levenspartner Korrin geniet enorm van nieuwe kleren, dus ik wil een nieuwe mantel voor haar maken, versierd met de ragfijne vleugels van feeëndraken. Kun je me helpen? De sprite darters met de prachtige vleugels die ik wil, zitten ten westen van Camp Mojache.",
  o = "Breng 10 Iridescent Sprite Darter Wings naar Krueg Skullsplitter in Camp Mojache.",
  p = "De sprite darters kunnen gevaarlijke beestjes zijn als ze geprovoceerd worden. Wees voorzichtig met ze, $c. En wees nog voorzichtiger met nachtelfen in de buurt. Die irritante dwazen houden zich ook graag op in de bossen.$B$BLaat het me weten als je genoeg vleugels hebt. Ik zorg ervoor dat je goed beloond wordt!",
  c = "Geweldig, $c! Deze zijn prima. Het zijn er genoeg voor een mantel voor Korrin, en misschien zelfs meer! Dank je.$B$BIk hoop dat de tocht niet te gevaarlijk was? Feralas staat er niet om bekend dat het vergevingsgezind is, maar jij hebt het duidelijk goed genoeg gedaan.$B$BNogmaals bedankt, $c.",
  g = { {"glans", "sheen, shine"}, {"mantel", "cloak"}, {"gegroet", "well met, greetings"}, {"metgezellen", "companions (metgezel)"}, {"levenspartner", "life-mate"}, {"geniet", "takes pleasure (genieten)"}, {"versierd", "adorned (versieren)"}, {"ragfijne", "gossamer, delicate (ragfijn)"}, {"feeëndraken", "faerie dragons (feeëndraak)"}, {"geprovoceerd", "provoked (provoceren)"}, {"irritante", "pestering, annoying (irritant)"}, {"houden zich op", "hang about (zich ophouden)"}, {"staat er niet om bekend", "is not known for (bekendstaan)"}, {"vergevingsgezind", "forgiving"} },
},

[2974] = { en = "A Grim Discovery", tier = 3,
  t = "Een grimmige ontdekking",
  d = "Wat!? Ben je tauren tegengekomen in deze streek? Je maakt een grapje! Hoe zagen ze eruit!?$B$BDe Grimtotem-clan! Heb je een paar van hen gevonden? Belgrom, een van onze meesters, is in hun soort geïnteresseerd... hij heeft zelfs een premie op ze gezet.$B$BJe moet teruggaan, $c. Ga terug en breng me hun hoorns... stapels, als het lukt. Met de Grimtotem valt niet te spotten, en je mag ze niet onderschatten. Ga terug en dood ze; laat de rivieren in Feralas rood kleuren van hun duistere bloed.",
  o = "Breng 20 Grimtotem Horns naar Krueg Skullsplitter in Camp Mojache.",
  p = "Neem mijn woorden serieus, $c: de Grimtotem-clan is slecht. Als je hebt ontdekt waar ze zitten, dan is het aan jou om terug te gaan en de eerste klap tegen hun clan uit te delen... voordat ze ons eigen land binnenvallen en onze eigen dorpen platbranden, of ons land plunderen.",
  c = "Dit zijn goede hoorns, $c. Goed gedaan. Ik neem ze van je over en vertel het Belgrom meteen als we terug zijn in Orgrimmar. Je hebt me nu twee keer geholpen, en daarom heb je mijn erkenning. Misschien kan ik jou in de toekomst helpen! Veel succes.",
  g = { {"grimmige", "grim (grimmig)"}, {"ontdekking", "discovery"}, {"tegengekomen", "came across (tegenkomen)"}, {"premie", "bounty"}, {"hoorns", "horns (hoorn)"}, {"stapels", "piles (stapel)"}, {"onderschatten", "to underestimate"}, {"de eerste klap uitdelen", "to strike the first blow"}, {"binnenvallen", "to invade"}, {"platbranden", "to burn down, to raze"}, {"plunderen", "to pilfer, to plunder"}, {"erkenning", "recognition, mark"} },
},

[2976] = { en = "A Grim Discovery", tier = 3,
  t = "Een grimmige ontdekking",
  d = "Wat?!$B$BAh, dus ik heb het over een premie gehad, hè? Nou, dat zal me leren om mijn mond open te doen, niet?$B$BJij hebt het werk gedaan, dus het is eigenlijk niet meer dan eerlijk dat jij de grootste beloning krijgt. Neem de hoorns; ik laat ze voor je in een kist doen. Zoek Belgrom Rockmaul in de Valley of Honor. Hij wil weten wat je hebt gezien, en hij beloont je voor je harde werk.$B$BHet ga je goed, $c, en nogmaals bedankt voor alles wat je hebt gedaan.",
  o = "Breng de Crate of Grimtotem Horns naar Belgrom Rockmaul in Orgrimmar.",
  p = "Snel, $c, ik moet vandaag nog veel afmaken.",
  c = "De Grimtotem!? Dit is interessant. Zeg je dat je ze tegenkwam toen je in Feralas aan het jagen was? Echt waar?$B$BMijn collega's zullen je nieuws willen horen, $c. Vertel me meer, dan tel ik ondertussen je geld uit.$B$BEn voor je gaat: weet dat ik je dankbaar ben voor de informatie die je me vandaag hebt gegeven.",
  g = { {"premie", "bounty"}, {"dat zal me leren", "that'll teach me"}, {"niet meer dan eerlijk", "only right, only fair"}, {"kist", "crate"}, {"het ga je goed", "be well, farewell"}, {"afmaken", "to complete, to finish"}, {"tegenkwam", "came across (tegenkomen)"}, {"collega's", "peers, colleagues (collega)"}, {"ondertussen", "meanwhile"}, {"tel uit", "count out (uittellen)"}, {"dankbaar", "grateful"} },
},

[3121] = { en = "A Strange Request", tier = 3,
  t = "Een vreemd verzoek",
  d = "Neeru Fireblade in Orgrimmar heeft wat ik nodig heb om hier te beginnen! Hij heeft een brouwsel gemengd dat ik nodig heb voor mijn... nou ja, dat zie je wel.$B$BEn nu op weg -- naar Orgrimmar. Hier, neem dit mee. Het is een gekrompen hoofd dat ik Neeru heb beloofd in ruil voor de kruiden. Het is het hoofd van een arme dwerg die ik in het bos tegenkwam. Ik weet zeker dat Neeru er blij mee zal zijn.$B$BJe vindt Neeru in de Cleft of Shadow.",
  o = "Breng het Shrunken Head naar Neeru Fireblade in Orgrimmar.",
  p = "Ja?",
  c = "Ik wachtte al tot Uzer'i dit zou brengen...$B$BIk geef je het kruidenmengsel dat ik heb klaargemaakt voor zijn... nou ja, experimenten...",
  g = { {"verzoek", "request"}, {"brouwsel", "concoction, brew"}, {"gemengd", "mixed (mengen)"}, {"gekrompen", "shrunken (krimpen)"}, {"in ruil voor", "in exchange for"}, {"kruiden", "herbs (kruid)"}, {"dwerg", "dwarf"}, {"tegenkwam", "came across (tegenkomen)"}, {"kruidenmengsel", "herb mixture"}, {"klaargemaakt", "prepared (klaarmaken)"} },
},

[3122] = { en = "Return to Witch Doctor Uzer'i", tier = 3,
  t = "Terug naar Witch Doctor Uzer'i",
  d = "Hier zijn de kruiden, $N. Breng ze naar Witch Doctor Uzer'i.$B$BZeg hem alsjeblieft dat ik tevreden ben met het gekrompen hoofd.",
  o = "Breng Neeru's Herb Pouch naar Witch Doctor Uzer'i in Feralas.",
  p = "Heb je met Neeru gesproken?",
  c = "Dit is precies wat ik nodig heb om het muisek-vat klaar te maken, $N. Binnenkort zien we of mijn nieuwste bezweringen zo krachtig zijn als ik had gehoopt.$B$BEven een moment, alsjeblieft. Ik moet het ritueel uitvoeren en de kruiden aanbrengen.",
  g = { {"kruiden", "herbs (kruid)"}, {"tevreden", "satisfied"}, {"gekrompen", "shrunken (krimpen)"}, {"vat", "vessel"}, {"bezweringen", "incantations (bezwering)"}, {"krachtig", "powerful"}, {"ritueel", "ritual"}, {"uitvoeren", "to perform"}, {"aanbrengen", "to apply"} },
},

[3125] = { en = "Faerie Dragon Muisek", tier = 3,
  t = "Muisek van een feeëndraak",
  d = "$N, nu moet je een wezen voor me vangen dat er heel breekbaar uit kan zien, maar het gaat ons juist om zijn krachtige geest. De feeëndraken waar ik het over heb, zijn bondgenoten van de nachtelfen geweest. We moeten er een vangen, zodat de Horde ook kan profiteren van deze geestkracht.$B$BHier is de muisek, $N. Dood 8 sprite darters of sprite dragons, en vang hun muisek. Je vindt ze ten westen van hier.",
  o = "Dood 8 Sprite Darters of Sprite Dragons. Gebruik het Muisek Vessel om de gevallen Faerie Dragons te laten krimpen en te vangen.",
  p = "Is het je gelukt om de muisek van de feeëndraken te vangen?",
  c = "Dank je, $N. Nu kunnen we de geestelijke krachten van de feeëndraak gebruiken.$B$BIk hoop dat je bereid bent om nog een taak voor me te doen.",
  g = { {"feeëndraak", "faerie dragon"}, {"wezen", "creature"}, {"breekbaar", "fragile"}, {"het gaat ons om", "what we are after"}, {"geest", "spirit"}, {"bondgenoten", "allies (bondgenoot)"}, {"profiteren", "to benefit"}, {"geestkracht", "strength of spirit"}, {"gevallen", "fallen"}, {"krimpen", "to shrink"}, {"geestelijke", "spiritual (geestelijk)"}, {"bereid", "willing"} },
},

[793] = { en = "Broken Alliances", tier = 4,
  t = "Gebroken bondgenootschappen",
  d = "Het Seal of the Earth wordt vastgehouden door drie runestenen, die zich in de Pillars of Diamond, Opal en Amethyst in Lethlor Ravine bevinden. Met het Sign of the Earth kun je de runestenen weghalen en het Seal of the Earth openen.$b$bMaar wees op je hoede, $n: met de zwarte draken Blacklash en Hematus valt niet te spotten. Zorg dat ze sterven en breng hun boeien naar mij.$B$BOm de kloof te bereiken, reis je naar het uiterste oosten van de Badlands. Maar wees voorzichtig, want in de kloof wonen talloze draken.",
  o = "Gebruik het Sign of the Earth om de Pillars of Diamond, Opal en Amethyst te activeren en de Runestones te krijgen.$b$bLeg de runestenen in het zegel om Blacklash en Hematus te bevrijden.$b$bDood ze en breng Blacklash's Bindings, de Chains of Hematus en het Sign of the Earth naar Gorn.",
  p = "Er zijn weinig vijanden dodelijker dan het drakenvolk, en er waren weinig draken die zo woest vochten als Blacklash en Hematus.",
  c = "De zwarte drakenvlucht blijft zich verbinden met de afvallige Blackrock-orks, en beide moeten in het gareel worden gebracht, of verwijderd. Nu Blacklash en Hematus dood zijn, kunnen we onze aandacht op het westen richten, op Blackrock Spire.",
  g = { {"vastgehouden", "held (vasthouden)"}, {"runestenen", "runestones (runesteen)"}, {"bevinden", "are located (zich bevinden)"}, {"wees op je hoede", "be wary"}, {"valt niet te spotten", "are not to be trifled with (spotten met)"}, {"boeien", "bindings, shackles (boei)"}, {"kloof", "ravine"}, {"uiterste", "farthest, extreme"}, {"talloze", "countless (talloos)"}, {"drakenvolk", "dragonkind"}, {"woest", "ferociously, fiercely"}, {"drakenvlucht", "dragonflight"}, {"afvallige", "renegade (afvallig)"}, {"in het gareel worden gebracht", "be brought into line"}, {"aandacht", "attention"} },
},

[795] = { en = "Seal of the Earth", tier = 4,
  t = "Het Seal of the Earth",
  p = "Hier ligt het Seal of the Earth, met drie uitgesneden nissen voor de Amethyst Runestone, de Opal Runestone en de Diamond Runestone.",
  c = "Terwijl je de runestenen in de passende nissen legt, schudt de aarde met een hevig gerommel, en het zegel breekt.",
  g = { {"uitgesneden", "recessed, cut out (uitsnijden)"}, {"nissen", "alcoves, recesses (nis)"}, {"passende", "matching (passend)"}, {"schudt", "shakes (schudden)"}, {"hevig", "violent, heavy"}, {"gerommel", "rumbling"}, {"zegel", "seal"} },
},

[3821] = { en = "Dreadmaul Rock", tier = 4,
  t = "Dreadmaul Rock",
  d = "Sha'ni werd meer dan drie weken geleden gestuurd om berichten te onderzoeken over vreemde rituele activiteiten bij de Firegut-ogres van de Burning Steppes.$B$BGoretooth zegt dat hij niets meer heeft gehoord van iemand uit dat peloton, en dat ik het beter kan loslaten en me op mijn taak moet richten. Kun je het geloven? Ze is mijn vrouw!$B$BIk kan mijn post niet verlaten, $N, maar ik moet weten wat er met Sha'ni is gebeurd. Reis naar de Burning Steppes en zoek haar.",
  o = "Trek naar de Burning Steppes en ontdek wat er met Sha'ni Proudtusk is gebeurd.",
  c = "Mijn arme Thal'trak.$B$BWe waren van plan om bij mijn moeder en vader in de Hinterlands te gaan wonen als onze diensttijd voorbij was. Nu zijn die plannen verwoest!",
  g = { {"berichten", "reports (bericht)"}, {"onderzoeken", "to investigate"}, {"rituele", "ritualistic (ritueel)"}, {"activiteiten", "activities (activiteit)"}, {"peloton", "platoon"}, {"loslaten", "to let go, move on"}, {"me richten", "focus (zich richten op)"}, {"post", "post"}, {"verlaten", "to leave"}, {"trek", "venture (trekken)"}, {"van plan", "planning"}, {"diensttijd", "tour of duty"}, {"verwoest", "ruined (verwoesten)"} },
},

[4062] = { en = "The Rise of the Machines", tier = 4,
  t = "De opkomst van de machines",
  d = "G.L.A.$B$BDat zijn de 'initialen' die in de elementaire scherven zijn gedrukt. Onder de initialen staat een soort rangteken. De machines die je in de Burning Steppes hebt vernietigd, waren van 'Rang IV'. Ik neem aan dat dat een lage rang is.$B$BBreng dit monster van de scherf naar Lotwil Veriatus in het kamp in het oosten. Hij is een vrij bekende geleerde op het gebied van de elementaire wetenschappen. Misschien kan hij ons helpen bij onze zoektocht.",
  o = "Breng het Elemental Shard Sample naar Lotwil Veriatus.$B$BJe herinnert je dat Theodora zei dat Lotwil in een kamp in het oosten zat.$b",
  p = "Wat heb je daar, $R?",
  c = "<Lotwil wordt lijkbleek.>$b$bIk... ik ken deze tekens.",
  g = { {"opkomst", "rise"}, {"initialen", "initials"}, {"elementaire", "elemental (elementair)"}, {"scherven", "shards (scherf)"}, {"gedrukt", "imprinted, pressed (drukken)"}, {"rangteken", "rank marking"}, {"vernietigd", "destroyed (vernietigen)"}, {"neem aan", "assume (aannemen)"}, {"monster", "sample"}, {"geleerde", "scholar"}, {"wetenschappen", "sciences (wetenschap)"}, {"zoektocht", "search"}, {"lijkbleek", "deathly pale, white as a sheet"}, {"tekens", "markings, signs (teken)"} },
},

})

